"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2059],{72059:e=>{e.exports=JSON.parse('{"slug":"ssha-otlozhili-poshliny-pokupatelyam-rossiyskoy-nefti","locale":"es","title":"Estados Unidos aplaza aranceles a compradores de crudo ruso y las acciones suben un 4,5% semanal","description":"Estados Unidos suspende aranceles de hasta el 100% a los mayores compradores de petr\xf3leo y gas rusos. C\xf3mo funcionan los aranceles secundarios y qu\xe9 significa la pausa.","blocks":[{"id":"b001","kind":"paragraph","text":"Donald Trump firm\xf3 el 18 de septiembre una ley de sanciones promovida por Lindsey Graham. Permit\xeda gravar hasta el 100% todos los productos importados de los 5 mayores compradores de petr\xf3leo y gas rusos. Deb\xeda activarse el 18 de octubre. Faltando 2 d\xedas, Trump suspendi\xf3 las medidas por decreto. La ley lo permite si informa al Congreso de que perjudican a Estados Unidos."},{"id":"b002","kind":"paragraph","text":"Marco Rubio explic\xf3 dos razones: no frustrar las conversaciones con Rusia y Ucrania y estudiar durante 60 d\xedas el efecto mundial. Afectar\xedan a India y China cuando ya falta crudo por Ormuz. El 16 de octubre, el Brent lleg\xf3 a $110, m\xe1ximo desde mayo. Los analistas tambi\xe9n se\xf1alan las elecciones al Congreso del 3 de noviembre: el combustible caro perjudica al votante estadounidense."},{"id":"b003","kind":"paragraph","text":"Imagina un mercado que multa a quien compra verduras a cierto agricultor. Paga el cliente, pero tambi\xe9n pierde el vendedor: debe rebajar o buscar a quien no tema la multa. As\xed operan los aranceles secundarios. China compr\xf3 combustibles rusos en septiembre por unos 9,1 mil millones de euros; India, por 4,1 mil millones. Gravar hasta el 100% de todo su comercio con Estados Unidos las obligar\xeda a elegir o exigir un descuento mayor."},{"id":"b004","kind":"paragraph","text":"El descuento frente al mundo determina lo que Rusia recibe por barril. El Urals promedi\xf3 $92,08 en septiembre. India ya diversifica: la cuota rusa baj\xf3 del 51% en julio al 44% en agosto, con m\xe1s compras a Estados Unidos y Emiratos. La pausa retira temporalmente el riesgo de perder compradores o conceder mayores rebajas."},{"id":"b005","kind":"paragraph","text":"Los inversores interpretaron la pausa como una opci\xf3n de aliviar sanciones; tambi\xe9n ayud\xf3 el petr\xf3leo caro. El \xedndice de Mosc\xfa subi\xf3 del 12 al 16 de octubre un 4,51%, a 2426 puntos. El domingo 18 lleg\xf3 en sesi\xf3n de fin de semana a casi 2450, m\xe1ximo de 3 meses. El rublo mejor\xf3 menos: el d\xf3lar oficial del 17–19 de octubre era 83,62, frente a 84,90 una semana antes. El Brent baj\xf3 un 2% la ma\xf1ana del 19, a $107,6, al esperarse m\xe1s combustible ruso disponible."},{"id":"b006","kind":"paragraph","text":"El decreto no deroga la ley y el presidente puede restaurar los aranceles. Se espera una decisi\xf3n despu\xe9s de las elecciones del 3 de noviembre y del G20 de diciembre en Miami. Renunciar a ellos preservar\xeda compradores y descuentos; aplicarlos obligar\xeda a India y China a recalcular, presionando exportaciones y presupuesto. La subida burs\xe1til refleja en gran parte una esperanza todav\xeda no asegurada."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 aranceles se aplazaron?"},{"id":"b008","kind":"paragraph","text":"La ley del 18 de septiembre de 2026 permit\xeda desde el 18 de octubre gravar hasta el 100% los productos de los 5 mayores compradores de petr\xf3leo y gas rusos. Trump suspendi\xf3 las medidas el 16 de octubre."},{"id":"b009","kind":"heading","text":"\xbfC\xf3mo perjudican a Rusia los aranceles contra India y China?"},{"id":"b010","kind":"paragraph","text":"El cliente debe elegir entre petr\xf3leo ruso y mercado estadounidense para sus productos. Para retenerlo, el vendedor baja el precio. Rusia recibe menos por barril y concede un descuento mayor frente a la referencia mundial."},{"id":"b011","kind":"heading","text":"\xbfCu\xe1ndo tomar\xe1 Estados Unidos la decisi\xf3n definitiva?"},{"id":"b012","kind":"paragraph","text":"Rubio habl\xf3 de hasta 60 d\xedas. Se espera despu\xe9s de las elecciones del 3 de noviembre y del G20 de diciembre en Miami. El decreto no elimina la ley: los aranceles pueden volver en cualquier momento."}],"sources":[{"label":"Trump firma una exenci\xf3n de las nuevas sanciones rusas","url":"https://www.themoscowtimes.com/2026/10/17/trump-signs-order-exempting-russia-from-new-sanctions-legislation-a94012"},{"label":"Trump suspende aranceles vinculados a Rusia y alivia a India","url":"https://www.outlookindia.com/international/trump-suspends-russia-linked-tariffs-india-russian-oil"},{"label":"Qu\xe9 supone para Ucrania la exenci\xf3n de sanciones","url":"https://time.com/article/2026/10/17/what-trump-s-waiver-of-new-russia-sanctions-means-for-ukraine/"},{"label":"Trump aplaza las sanciones dr\xe1sticas","url":"https://www.kommersant.ru/doc/9041600"},{"label":"El petr\xf3leo baja desde el m\xe1ximo de 5 meses por la exenci\xf3n rusa","url":"https://www.brecorder.com/news/40444883/oil-slips-from-5-month-high-as-trumps-russia-sanctions-waiver-may-bring-more-supplies"},{"label":"Septiembre de 2026: exportaci\xf3n rusa de combustibles y sanciones","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"},{"label":"El crudo ruso se encarece casi una vez y media","url":"https://lenta.ru/news/2026/10/05/urals/"},{"label":"El \xedndice de Mosc\xfa gana un 25% en tres meses","url":"https://www.vbr.ru/novosti/investicii/2026/10/19/indeks-mosbirji-pribavil-25-za-tri-mesyaca/"},{"label":"El banco central fija el d\xf3lar del 17–19 de octubre en 83,62 rublos","url":"https://finance.rambler.ru/economics/57237637-tsb-ponizil-kurs-dollara-na-17-19-oktyabrya-do-83-62-rublya/"},{"label":"Tipo del d\xf3lar del 10 de octubre de 2026","url":"https://ppt.ru/currencies/usd/10-10-2026"}],"sourceBodySha256":"08a9ef35b4b6638b9180eb959dc7416a99027fabfd65ad99f9ce3dbcf52878d0"}')}}]);